const toRad = (deg) => deg * Math.PI / 180;

// Coordinates
const lat1 = 37.7749, lon1 = -122.4194; // San Francisco, CA
const lat2 = 42.3601, lon2 = -71.0589;  // Boston, MA

// Haversine formula
const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));

const rKm = 6371.0;
const rMi = 3958.8;

const distKm = (rKm * c).toFixed(2);
const distMi = (rMi * c).toFixed(2);

console.log('From: San Francisco, CA (37.7749°N, 122.4194°W)');
console.log('To:   Boston, MA (42.3601°N, 71.0589°W)');
console.log('');
console.log('Straight-line (great-circle) distance:');
console.log('  ' + distKm + ' km');
console.log('  ' + distMi + ' miles');
"
